import { precacheAndRoute, cleanupOutdatedCaches } from 'workbox-precaching';
import { registerRoute } from 'workbox-routing';
import { NetworkFirst, CacheFirst, StaleWhileRevalidate } from 'workbox-strategies';
import { clientsClaim } from 'workbox-core';

// SW build identity (unique per build)
const SW_VERSION = `padh-sw-${__BUILD_ID__ || Date.now()}`;
const SW_BUILT_AT = new Date().toISOString();

// Immediate skip waiting and claim clients
self.skipWaiting();
clientsClaim();

// Precache all assets generated by Vite
const __MANIFEST__ = self.__WB_MANIFEST || [];
precacheAndRoute(__MANIFEST__);
cleanupOutdatedCaches();

// Standard PWA routes
registerRoute(
  ({ request }) => request.mode === 'navigate' || request.destination === 'document',
  new NetworkFirst({
    cacheName: 'html-freshness',
    networkTimeoutSeconds: 3,
  })
);

registerRoute(
  ({ request }) =>
    request.destination === 'script' ||
    request.destination === 'style' ||
    request.destination === 'worker',
  new NetworkFirst({
    cacheName: 'bundles-freshness',
    networkTimeoutSeconds: 3,
  })
);

registerRoute(
  ({ url }) => url.pathname === '/changelog' || url.pathname === '/sobre',
  new StaleWhileRevalidate({
    cacheName: 'informational-swr',
  })
);

registerRoute(
  /\.(?:png|jpg|jpeg|svg|gif|webp|woff2?|ttf|otf)$/i,
  new CacheFirst({
    cacheName: 'static-assets-v1',
  })
);

// --- Daily Reminder Logic with Robust Persistence & Fallback ---

let reminderConfig = null;
let memoryLastNotifiedDate = null;

// IndexedDB with Fallback
const dbPromise = new Promise((resolve) => {
  try {
    const request = indexedDB.open('padh-sw-db', 2);
    request.onupgradeneeded = (e) => {
      if (!e.target.result.objectStoreNames.contains('settings')) {
        e.target.result.createObjectStore('settings');
      }
    };
    request.onsuccess = (e) => resolve(e.target.result);
    request.onerror = () => resolve(null); // Fallback to memory
  } catch (e) {
    resolve(null);
  }
});

async function getSetting(key) {
  const db = await dbPromise;
  if (!db) return memoryLastNotifiedDate; // Basic fallback
  return new Promise((resolve) => {
    try {
      const transaction = db.transaction('settings', 'readonly');
      const request = transaction.objectStore('settings').get(key);
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => resolve(null);
    } catch (e) {
      resolve(null);
    }
  });
}

async function setSetting(key, value) {
  if (key === 'last_notified_date') memoryLastNotifiedDate = value;
  
  const db = await dbPromise;
  if (!db) return;
  return new Promise((resolve) => {
    try {
      const transaction = db.transaction('settings', 'readwrite');
      transaction.objectStore('settings').put(value, key);
      transaction.oncomplete = () => resolve();
      transaction.onerror = () => resolve();
    } catch (e) {
      resolve();
    }
  });
}

let continuousTestInterval = null;
let testCount = 0;

// Handler for all messages
const handleMessage = async (event) => {
  if (!event.data) return;

  switch (event.data.type) {
    case 'SKIP_WAITING':
      self.skipWaiting();
      break;

    case 'SET_REMINDER':
      reminderConfig = event.data;
      await setSetting('reminder_config', reminderConfig);
      break;

    case 'START_CONTINUOUS_TEST':
      testCount = 0;
      if (continuousTestInterval) clearInterval(continuousTestInterval);
      
      continuousTestInterval = setInterval(async () => {
        testCount++;
        const config = event.data.config || reminderConfig;
        await self.registration.showNotification(`Teste Contínuo #${testCount}`, {
          body: `Entrega ${testCount}: ${config?.message || "Validando fluxo."}`,
          icon: "/pwa-192x192.png",
          tag: 'continuous-test',
          data: { isTest: true }
        });
        
        const clientsList = await clients.matchAll();
        clientsList.forEach(client => client.postMessage({ type: 'TEST_COUNT_UPDATE', count: testCount }));
      }, 30000);
      break;

    case 'STOP_CONTINUOUS_TEST':
      if (continuousTestInterval) clearInterval(continuousTestInterval);
      continuousTestInterval = null;
      break;

    case 'TEST_NOTIFICATION': {
      const config = event.data.config || reminderConfig;
      const timeInfo = config ? ` [Agendado: ${config.time}]` : "";
      
      await self.registration.showNotification("Teste de Lembrete PADH" + timeInfo, {
        body: config?.message || "Esta é uma demonstração do seu lembrete diário.",
        icon: "/pwa-192x192.png",
        tag: 'test-notification',
        data: { isTest: true },
        actions: [{ action: 'open_checkin', title: 'Abrir Check-in' }]
      });

      if (event.source) {
        event.source.postMessage({ type: 'TEST_CONFIRMATION', status: 'delivered' });
      }
      break;
    }

    case 'GET_TECHNICAL_INFO': {
      const lastNotified = await getSetting('last_notified_date');
      const config = reminderConfig || await getSetting('reminder_config');
      const db = await dbPromise;
      
      if (event.source) {
        event.source.postMessage({
          type: 'TECHNICAL_INFO_RESPONSE',
          info: {
            lastNotified,
            config,
            continuousMode: !!continuousTestInterval,
            testCount,
            swStatus: 'active',
            timestamp: new Date().toISOString(),
            persistence: db ? 'IndexedDB' : 'Memory Fallback'
          }
        });
      }
      break;
    }

    case 'GET_SW_VERSION': {
      if (event.source) {
        event.source.postMessage({
          type: 'SW_VERSION_RESPONSE',
          version: SW_VERSION,
          builtAt: SW_BUILT_AT,
          manifestCount: __MANIFEST__.length,
        });
      }
      break;
    }

    case 'GET_PRECACHE_MANIFEST': {
      // Return the list of precached files (url + revision)
      const files = __MANIFEST__.map((entry) => {
        if (typeof entry === 'string') return { url: entry, revision: null };
        return { url: entry.url, revision: entry.revision || null };
      });
      if (event.source) {
        event.source.postMessage({
          type: 'PRECACHE_MANIFEST_RESPONSE',
          files,
          builtAt: SW_BUILT_AT,
          version: SW_VERSION,
        });
      }
      break;
    }
  }
};

self.addEventListener('message', (event) => {
  event.waitUntil(handleMessage(event));
});

async function checkAndShowNotification() {
  const config = reminderConfig || await getSetting('reminder_config');
  if (!config || !config.enabled) return;

  const now = new Date();
  const today = now.toLocaleDateString('sv');
  const lastNotified = await getSetting('last_notified_date');
  
  if (lastNotified === today) return;

  const [targetHours, targetMinutes] = config.time.split(':').map(Number);
  
  if (now.getHours() === targetHours && now.getMinutes() === targetMinutes) {
    await setSetting('last_notified_date', today);
    const reminderId = `rem_${Date.now()}`;
    
    return self.registration.showNotification("Lembrete PADH", {
      body: config.message,
      icon: "/pwa-192x192.png",
      tag: 'daily-reminder',
      requireInteraction: true,
      data: { url: `/?from_notification=true&rid=${reminderId}` },
      actions: [{ action: 'open_checkin', title: 'Fazer Check-in agora' }]
    });
  }
}

self.addEventListener('periodicsync', (event) => {
  if (event.tag === 'daily-reminder') {
    event.waitUntil(checkAndShowNotification());
  }
});

self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  const urlToOpen = event.notification.data?.url || '/';

  event.waitUntil(
    clients.matchAll({ type: 'window', includeUncontrolled: true }).then((clientList) => {
      for (const client of clientList) {
        if (client.url.includes(urlToOpen) && 'focus' in client) {
          return client.focus();
        }
      }
      if (clients.openWindow) return clients.openWindow(urlToOpen);
    })
  );
});
